import json

from openvino.runtime import Model, PartialShape, Type      # pylint: disable=no-name-in-module,import-error
from openvino.runtime.utils.types import get_dtype           # pylint: disable=no-name-in-module,import-error


def json_model_analysis_dump(framework_model: Model) -> None:

    def dump_partial_shape(partial_shape: PartialShape):
        if partial_shape.rank.is_dynamic:
            return 'None'

        shape = []
        for i in range(partial_shape.rank.get_length()):
            dim = partial_shape.get_dimension(i)
            shape.append(dim.get_length() if dim.is_static else 0)
        return shape

    def dump_element_type(ov_type: Type):
        try:
            return str(get_dtype(ov_type))
        except Exception:  # pylint: disable=broad-except
            return 'None'

    json_dump = {}
    json_dump['inputs'] = {}
    for param in framework_model.get_parameters():
        param_name = param.get_friendly_name()
        json_dump['inputs'][param_name] = {
            'shape': dump_partial_shape(param.get_partial_shape()),
            'data_type': dump_element_type(param.get_element_type()),
            'value': 'None',  # data is not accessible during model analysis
        }

    json_dump['intermediate'] = {}
    for op in framework_model.get_ordered_ops():
        for out in op.outputs():
            for name in out.get_names():
                json_dump['intermediate'][name] = {
                    'shape': dump_partial_shape(out.get_partial_shape()),
                    'data_type': dump_element_type(out.get_element_type()),
                    'value': 'None',  # data is not accessible during model analysis
                }

    json_model_analysis_print(json_dump)


def json_model_analysis_print(json_dump: dict) -> None:
    print(json.dumps(json_dump))
